/// Extension of table WMSJournalTable
/// </summary>
[ExtensionOf(tableStr(WMSJournalTable))]
final class AVAWMSJournalTableDbt_Extension
{
}

Method.Source:
/// <summary>
/// NS Zelinka 26.02.24
/// CoC method for validateDelete
/// </summary>
/// <returns>boolean value - true or false</returns>
public boolean validateDelete()
{
    boolean ret = next validateDelete();

    if (ret         &&
        this.Posted &&
        (this.JournalType == WMSJournalType::Reception    ||
         this.JournalType == WMSJournalType::Production)      )
    {
        ret = checkFailed("@NDX:NXAPostedRecordCanNotDeleted");
    }

    return ret;
}
